SELECT FROM company
WHERE company_id LIKE CONCAT('%', #{keyword}, '%') OR company_name LIKE CONCAT('%', #{keyword}, '%') OR company_type LIKE CONCAT('%', #{keyword}, '%')
ORDER BY company_id LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE company
SET company_name=#{form.companyName}, company_type=#{form.companyType}, address=#{form.address},
    postcode=#{form.postcode}, phone_number=#{form.phoneNumber}
WHERE company_id=#{companyId}
